#include <stdio.h>

/* Function to find common elements in two arrays */
int common_elements(int arr1[], int arr2[], int len)
{
    int i, j, flag, common_elements = 0;
    for (i = 0; i < len; i++) {
        flag = 1;
        for (j = 0; j < len; j++) {
            if (arr1[i] == arr2[j]) {
                flag = 0;
                break;
            }
            if (flag == 0) {
                common_elements++;
                break;
            }
        }
        if (common_elements == 0) {
            common_elements = 1;
            break;
        }
    }
    return common_elements;
