    printf("Common elements in arr1 and arr2:\n");
    printf("Size of arr1: %d\n", len);
    printf("Size of arr2: %d\n", len);
    printf("Common elements: %d\n", common_elements(arr1, arr2, len));
    return 0;
}
```

